// Fast lookup by ID
export const LESSON_BY_ID = Object.fromEntries(DAILY_LESSONS.map(l => [l.id, l]))

// Lessons grouped by topic
export function getLessonsByTopic(topicId) {
  return DAILY_LESSONS.filter(l => l.topicId === topicId)
}
